pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _test(string memory description) internal {
        vm.assume(c.jojoTeam() == address(0));
        vm.assume(msg.sender != c.jojoTeam());
        bool succeeded = false;
        try c.newEmergencyOracle(description) {
            succeeded = true;
        } catch {
            succeeded = false;
        }
        assertTrue(!succeeded);
    }

    function testFuzz_test(string memory description) public {
        _test(description);
    }

    receive() external payable {}
}
